class FinanceScreen extends StatefulWidget{const FinanceScreen({super.key});@override State<FinanceScreen> createState()=>_FinanceScreenState();}
class _FinanceScreenState extends State<FinanceScreen>{List<MoneyTransaction> tx=[];DateTime month=DateTime(DateTime.now().year,DateTime.now().month);
 @override void initState(){super.initState();_load();}Future<void> _load()async{tx=(await StorageService.read('finance')).map(MoneyTransaction.fromJson).toList();if(mounted)setState((){});}Future<void> _save()=>StorageService.write('finance',tx.map((e)=>e.toJson()).toList());
