 void _changeMonth(int d){setState(()=>month=DateTime(month.year,month.month+d));}
 @override Widget build(BuildContext context){final current=tx.where(_inMonth);final income=_sum(current.where((x)=>x.income)),expense=_sum(current.where((x)=>!x.income)),balance=income-expense;final allBalance=_sum(tx.where((x)=>x.income))-_sum(tx.where((x)=>!x.income));final byCat=<String,double>{};for(final x in current.where((x)=>!x.income))byCat[x.category]=(byCat[x.category]??0)+x.amount;return SafeArea(child:ListView(padding:const EdgeInsets.fromLTRB(16,12,16,28),children:[Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Financeiro',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold)),Text(DateFormat('MMMM yyyy','pt_BR').format(month))])),IconButton(onPressed:()=>_edit(),icon:const Icon(Icons.add_circle_outline))]),const SizedBox(height:12),AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[IconButton(onPressed:()=>_changeMonth(-1),icon:const Icon(Icons.chevron_left)),Expanded(child:Text(DateFormat('MMMM yyyy','pt_BR').format(month),textAlign:TextAlign.center,style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold))),IconButton(onPressed:()=>_changeMonth(1),icon:const Icon(Icons.chevron_right))]),const Divider(),Text('Saldo acumulado',style:Theme.of(context).textTheme.bodyMedium),Text('R$ ${allBalance.toStringAsFixed(2)}',style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold))])),Row(children:[Expanded(child:_metric('Entradas',income,Icons.south_west)),const SizedBox(width:8),Expanded(child:_metric('Despesas',expense,Icons.north_east)),const SizedBox(width:8),Expanded(child:_metric('Resultado',balance,Icons.account_balance_wallet_outlined))]),AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Entradas x despesas',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:14),_bar('Entradas',income,1),const Siz