 Widget _metric(String label,double value,IconData icon)=>Expanded(child:AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(icon),const SizedBox(height:6),Text('R$ ${value.toStringAsFixed(0)}',style:Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.bold)),Text(label,style:Theme.of(context).textTheme.bodySmall)])));
 Widget _bar(String label,double value,double total){final pct=total<=0?0.0:(value/total).clamp(0.0,1.0).toDouble();return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(label)),Text('R$ ${value.toStringAsFixed(2)}')]),const SizedBox(height:5),ClipRRect(borderRadius:BorderRadius.circular(8),child:LinearProgressIndicator(value:pct,minHeight:9))]);}
 Future<void> _delete(MoneyTransaction x)async{tx.remove(x);await _save();if(mounted)setState((){});}
